import{_ as r,o as a,c as t,a2 as s}from"./chunks/framework.DaGSOal_.js";const f=JSON.parse('{"title":"R","description":"","frontmatter":{},"headers":[],"relativePath":"glossaire-a-z/r.md","filePath":"glossaire-a-z/r.md"}'),n={name:"glossaire-a-z/r.md"};function i(o,e,l,d,c,p){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h1><h2 id="realfi" tabindex="-1">RealFi <a class="header-anchor" href="#realfi" aria-label="Permalink to &quot;RealFi&quot;">​</a></h2><p>Un concept propre à Cardano qui met l’accent sur les applications de finance décentralisée (<em>DeFi</em>) liées à l’activité économique réelle. Il couvre notamment des cas d’utilisation comme les prêts, l’identité numérique et les solutions de chaîne d’approvisionnement.</p><h2 id="real-world-assets-rwas-fr-actifs-du-monde-reel" tabindex="-1">Real World Assets (RWAs) (fr : Actifs du monde réel) <a class="header-anchor" href="#real-world-assets-rwas-fr-actifs-du-monde-reel" aria-label="Permalink to &quot;Real World Assets (RWAs) (fr : Actifs du monde réel)&quot;">​</a></h2><p>Désigne des actifs physiques ou des actifs financiers traditionnels, notamment lorsqu’ils sont tokenisés et représentés sur une blockchain.</p><h2 id="redeemer-fr-donnee-de-redemption" tabindex="-1">Redeemer (fr : Donnée de rédemption) <a class="header-anchor" href="#redeemer-fr-donnee-de-redemption" aria-label="Permalink to &quot;Redeemer (fr : Donnée de rédemption)&quot;">​</a></h2><p>Une donnée fournie à un contrat intelligent Cardano lors d’une tentative de dépense d’une sortie de transaction. Associée aux datums et aux scripts, elle permet de déterminer si les conditions de dépense sont satisfaites.</p><h2 id="reference-input-fr-entree-de-reference" tabindex="-1">Reference Input (fr : Entrée de référence) <a class="header-anchor" href="#reference-input-fr-entree-de-reference" aria-label="Permalink to &quot;Reference Input (fr : Entrée de référence)&quot;">​</a></h2><p>Une entrée de transaction qui permet de lire les données d’un UTxO sans le dépenser. Elle permet de consulter des informations enregistrées sur la chaîne sans retirer cet UTxO de l’ensemble des UTxO disponibles.</p><h2 id="reference-script-fr-script-de-reference" tabindex="-1">Reference Script (fr : Script de référence) <a class="header-anchor" href="#reference-script-fr-script-de-reference" aria-label="Permalink to &quot;Reference Script (fr : Script de référence)&quot;">​</a></h2><p>Un script Plutus attaché une seule fois à un UTxO, puis référencé — sans être inclus à nouveau — par les transactions ultérieures qui en ont besoin.</p><h2 id="reliability-fr-fiabilite" tabindex="-1">Reliability (fr : Fiabilité) <a class="header-anchor" href="#reliability-fr-fiabilite" aria-label="Permalink to &quot;Reliability (fr : Fiabilité)&quot;">​</a></h2><p>Désigne la capacité d’un système blockchain à fonctionner de manière constante et fiable, notamment pour le traitement des transactions et la production des blocs.</p><h2 id="representational-state-transfer-application-programming-interfaces-rest-apis-fr-interfaces-de-programmation-rest" tabindex="-1">Representational State Transfer Application Programming Interfaces (REST APIs) (fr : Interfaces de programmation REST) <a class="header-anchor" href="#representational-state-transfer-application-programming-interfaces-rest-apis-fr-interfaces-de-programmation-rest" aria-label="Permalink to &quot;Representational State Transfer Application Programming Interfaces (REST APIs) (fr : Interfaces de programmation REST)&quot;">​</a></h2><p>Un style d’interface web qui permet à différents systèmes de communiquer de manière standardisée au moyen du protocole HTTP. Cardano propose des API REST par l’intermédiaire de son nœud et de services associés pour faciliter l’intégration avec des applications.</p><h2 id="reserve-fr-reserve" tabindex="-1">Reserve (fr : Réserve) <a class="header-anchor" href="#reserve-fr-reserve" aria-label="Permalink to &quot;Reserve (fr : Réserve)&quot;">​</a></h2><p>La réserve de Cardano correspond à la partie de l’offre d’ada qui n’a pas été distribuée au lancement du réseau et qui est conservée sur la chaîne pour soutenir sa durabilité à long terme. Elle est libérée progressivement selon les règles du protocole afin de contribuer au financement des récompenses de staking et de la trésorerie de Cardano.</p><h2 id="rewards-reward-fr-recompenses" tabindex="-1">Rewards / Reward (fr : Récompenses) <a class="header-anchor" href="#rewards-reward-fr-recompenses" aria-label="Permalink to &quot;Rewards / Reward (fr : Récompenses)&quot;">​</a></h2><p>Les ada distribués aux opérateurs de pools de staking et aux délégants pour leur participation au système de preuve d’enjeu de Cardano. Les récompenses proviennent des frais de transaction et de la réserve monétaire.</p><h2 id="rewards-wallet-fr-portefeuille-de-recompenses" tabindex="-1">Rewards Wallet (fr : Portefeuille de récompenses) <a class="header-anchor" href="#rewards-wallet-fr-portefeuille-de-recompenses" aria-label="Permalink to &quot;Rewards Wallet (fr : Portefeuille de récompenses)&quot;">​</a></h2><p>L’adresse à laquelle les récompenses de staking sont automatiquement distribuées aux détenteurs d’ada. Les délégants peuvent dépenser ces récompenses ou les déléguer à nouveau sans déplacer leur mise principale.</p><h2 id="rollback-fr-retour-en-arriere" tabindex="-1">Rollback (fr : Retour en arrière) <a class="header-anchor" href="#rollback-fr-retour-en-arriere" aria-label="Permalink to &quot;Rollback (fr : Retour en arrière)&quot;">​</a></h2><p>Lorsqu’un nœud Cardano annule les blocs les plus récents parce que le réseau a convergé vers une autre branche de la blockchain.</p><h2 id="rosetta" tabindex="-1">Rosetta <a class="header-anchor" href="#rosetta" aria-label="Permalink to &quot;Rosetta&quot;">​</a></h2><p>Un standard ouvert développé par Coinbase pour simplifier l’intégration des blockchains. Cardano implémente les API Rosetta afin de faciliter la prise en charge de l’ada par les plateformes d’échange et les dépositaires.</p>',25)])])}const m=r(n,[["render",i]]);export{f as __pageData,m as default};
